#pragma once

// bw/signal/ppg_filter_chain.h — F02 §7: DC blocker + biquad band-pass
// (F02 D3/D7). Three Direct-Form I sections with coefficients generated by
// tools/design_ppg_filter.py (Butterworth Q = 1/sqrt(2), fs = 100 Hz):
//   1) DC blocker   high-pass 0.05 Hz — removes baseline wander,
//   2) band-pass    high-pass 0.5 Hz,
//   3) band-pass    low-pass  4.0 Hz  (30-240 bpm).
// The first sample primes every section to its DC steady state
// (x1 = x2 = x0, y1 = y2 = H(1)*x0), which removes the ~3 s DC-blocker
// startup transient that would otherwise fake peaks (F02 D7).

#include <bw/containers/ring_buffer.h>
#include <bw/signal/ppg_filter_coeffs.h>
#include <bw/signal/signal_config.h>
#include <bw/types.h>

namespace bw::signal {

// One point of the F28 debug tap: raw IR + filtered value. Implicit 10 ms
// spacing (kPpgSamplePeriodMs); gaps are visible as missing points (F02 D4).
struct PpgFilteredPoint {
    uint32_t ir_raw;
    float filtered;
};

class PpgFilterChain {
public:
    explicit PpgFilterChain(PpgProfile profile = PpgProfile::Filtered100Hz) : profile_(profile) {
        reset();
    }

    // Filters one raw IR sample and appends it to the F28 debug ring.
    float push(uint32_t ir_raw);

    // Back to the unprimed startup state (first push() re-seeds it).
    void reset();

    // Debug tap for F02 §3 / F28: copies up to max oldest-first points.
    size_t copyDebug(PpgFilteredPoint* out, size_t max) const;

private:
    // One biquad in Direct Form I (chosen for the exact steady-state priming,
    // F02 D7). Values are set from the generated coefficient header.
    struct Biquad {
        float b0, b1, b2, a1, a2;
        float x1, x2, y1, y2;

        float process(float x);
        void primeSteadyState(float x0);
        void clearState();
    };

    PpgProfile profile_;
    Biquad dc_blocker_;
    Biquad bandpass_hp_;
    Biquad bandpass_lp_;
    bool primed_ = false;
    RingBuffer<PpgFilteredPoint, kPpgFilteredDebugCapacity> debug_;
};

}  // namespace bw::signal
